'use strict';
const $=id=>document.getElementById(id), escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={active_gas:'Gas well',active_oil:'Oil well',active_oil_gas:'Oil / gas well',plugged:'Plugged',permitted:'Permitted location',canceled_or_abandoned_location:'Canceled / abandoned location',shut_in:'Shut-in',dry_hole:'Dry hole',injection_or_disposal:'Injection / disposal',observation:'Observation',service:'Service',water_supply:'Water supply'};
const colors={active_gas:'#4e8b65',active_oil:'#4e8b65',active_oil_gas:'#4e8b65',permitted:'#cc9c50',plugged:'#788c8a'};
const countyBounds=[[32.54,-97.57],[33.03,-97.03]];
const map=L.map('map',{zoomControl:false}).fitBounds(countyBounds); L.control.zoom({position:'topleft'}).addTo(map);
L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map);
let all=[], filtered=[], selected=null, markers=new Map(), cluster=L.markerClusterGroup({chunkedLoading:true,showCoverageOnHover:false,maxClusterRadius:55}); map.addLayer(cluster);
const markerFor=w=>L.marker([w.latitude_nad83,w.longitude_nad83],{title:`Well ${w.api_raw} ${w.well_number||''}`,icon:L.divIcon({className:'well-pin',html:'',iconSize:[12,12],iconAnchor:[6,6]})}).on('add',function(){const el=this.getElement();if(el)el.style.background=colors[w.regulatory_status]||'#a98c76'}).on('click',()=>showWell(w));
function showWell(w){selected=w.well_key;const d=$('detail');d.hidden=false;d.innerHTML=`<button class="detail-close" aria-label="Close details">×</button><div class="eyebrow">RRC WELL RECORD &nbsp; / &nbsp; TARRANT COUNTY</div><h2>${escapeHtml(w.api_raw||'Unidentified')}</h2><div class="subtitle">Well ${escapeHtml(w.well_number||'number unavailable')} · ${escapeHtml(labels[w.regulatory_status]||w.regulatory_status)}</div><dl><div><dt>RRC status</dt><dd>${escapeHtml(w.regulatory_status_raw||'Unavailable')}</dd></div><div><dt>Well number</dt><dd>${escapeHtml(w.well_number||'Unavailable')}</dd></div><div><dt>Coordinates (NAD83)</dt><dd>${Number(w.latitude_nad83).toFixed(5)}, ${Number(w.longitude_nad83).toFixed(5)}</dd></div><div><dt>Location source</dt><dd>${escapeHtml(w.location_source||'Unavailable')}</dd></div><div><dt>Location reliability</dt><dd>${escapeHtml(w.location_reliability||'Unavailable')}</dd></div><div><dt>Identity method</dt><dd>${w.identity_method==='spatial'?'Spatial estimate':escapeHtml(w.identity_method.replaceAll('_',' '))}</dd></div><div><dt>Source features</dt><dd>${w.source_feature_count}</dd></div><div><dt>RRC object ID</dt><dd>${w.canonical_object_id}</dd></div><div><dt>Observations</dt><dd>None in this dataset</dd></div></dl><p class="detail-note">${w.identity_review_required?'This record’s identity requires review. ':''}Locations and status are based on an RRC snapshot and may be incomplete or approximate. No emissions measurements are included.</p><a href="https://gis.rrc.texas.gov/GISViewer/" target="_blank" rel="noopener">Open RRC GIS Viewer ↗</a>`;d.querySelector('button').onclick=()=>{d.hidden=true;selected=null;renderList()};renderList()}
function renderList(){const bounds=map.getBounds();const visible=filtered.filter(w=>bounds.contains([w.latitude_nad83,w.longitude_nad83]));$('resultCount').textContent=`(${visible.length.toLocaleString()})`;const shown=visible.slice(0,100);$('results').innerHTML=shown.length?shown.map(w=>`<button class="result ${selected===w.well_key?'selected':''}" data-id="${escapeHtml(w.well_key)}"><span class="result-icon">⌖</span><span class="result-main"><strong>${escapeHtml(w.api_raw||'Unidentified')}</strong><small>Well ${escapeHtml(w.well_number||'number unavailable')} · RRC #${w.canonical_object_id}</small></span><span class="result-status">${escapeHtml(labels[w.regulatory_status]||w.regulatory_status)} &nbsp; ↗</span></button>`).join('')+(visible.length>100?`<div class="empty">Showing 100 of ${visible.length.toLocaleString()} records in view. Zoom in or refine your search.</div>`:''):'<div class="empty">No well records in this view. Move the map or change your filters.</div>';document.querySelectorAll('.result').forEach(b=>b.onclick=()=>{const w=all.find(x=>x.well_key===b.dataset.id);map.setView([w.latitude_nad83,w.longitude_nad83],Math.max(map.getZoom(),15));showWell(w)})}
function update(){const q=$('search').value.trim().toLowerCase(),status=$('status').value; filtered=all.filter(w=>(status==='all'||w.regulatory_status===status)&&(!q||[w.api_raw,w.well_key,w.well_number,String(w.canonical_object_id)].some(x=>String(x||'').toLowerCase().includes(q))));cluster.clearLayers();markers.clear();const layers=filtered.map(w=>{let m=markerFor(w);markers.set(w.well_key,m);return m});cluster.addLayers(layers);renderList()}
$('search').addEventListener('input',update);$('status').addEventListener('change',update);$('clearSearch').onclick=()=>{$('search').value='';update();$('search').focus()};$('reset').onclick=()=>{$('search').value='';$('status').value='all';$('place').value='';$('placeMessage').textContent='';$('detail').hidden=true;selected=null;map.fitBounds(countyBounds);update()};map.on('moveend',renderList);
$('placeForm').onsubmit=async e=>{e.preventDefault();let q=$('place').value.trim();if(!q)return;$('placeMessage').textContent='Searching places…';try{let url=new URL('https://nominatim.openstreetmap.org/search');url.search=new URLSearchParams({q:q+', Tarrant County, Texas',format:'jsonv2',limit:'1',countrycodes:'us'});let res=await fetch(url);if(!res.ok)throw Error();let data=await res.json();if(!data.length){$('placeMessage').textContent='No place found. Try a more specific address.';return}const p=data[0];const lat=Number(p.lat),lon=Number(p.lon);if(!Number.isFinite(lat)||!Number.isFinite(lon))throw Error();map.setView([lat,lon],14);$('placeMessage').textContent=`Showing ${p.display_name}`;}catch(err){$('placeMessage').textContent='Place search is unavailable. You can still navigate the map.'}};
fetch('wells.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{all=data.filter(w=>Number.isFinite(w.latitude_nad83)&&Number.isFinite(w.longitude_nad83));$('total').textContent=all.length.toLocaleString();[...new Set(all.map(w=>w.regulatory_status))].sort((a,b)=>(labels[a]||a).localeCompare(labels[b]||b)).forEach(s=>{let o=document.createElement('option');o.value=s;o.textContent=labels[s]||s;$('status').append(o)});update()}).catch(()=>{$('results').innerHTML='<div class="empty">Could not load well records. Please reload the page.</div>'});
